# DK ETT.  Ebeltoft - Trustrup
with detail = 2 {
    let et = path("d2.dk.ett");

    with railway = :first :pax :removed {
        with link = "point.dk.Ebeltoft" {
            statdot(et[:ebe]);
            slabel(:bottom, et[:ebe] + (0dt, 1dt), "Ebeltoft");
        }

        with link = "line.dk.ETT" {
            track(et[:ebe, :ebe + 9.21km]);
            line_label(:left:e, et[:ebe + 9.2km] << 0.5mt,
                (0dt, -0.2dt), "ETT"
            );
            track(et[:ebe + 9.19km, :tru.ye]);
        }
    }
}

